#[unsafe(no_mangle)]
pub unsafe extern "C" fn dh_Snapshot_open(
    path: Slice,
    dll_folders: Slice,
    smaps_path: ffi::OptionalString,
    options: bool,
    rebuild: bool,
    cache_directory: ffi::OptionalString,
    progress: ffi::Progress,
) -> Outcome {
    unsafe {
        ffi::call(|| {
            Ok(Owned::arc(Snapshot::open(
                ffi::string(path),
                ffi::slice::<Slice>(dll_folders)
                    .iter()
                    .map(|s| {
                        ffi::string(Slice {
                            data: s.data,
                            len: s.len,
                            stride: s.stride,
                        })
                        .to_owned()
                    })
                    .collect::<Vec<_>>(),
                smaps_path
                    .present
                    .then(|| ffi::string(smaps_path.value).to_owned()),
                AnalysisOptions {
                    native_memory_roots: options,
                },
                rebuild,
                cache_directory
                    .present
                    .then(|| ffi::string(cache_directory.value).to_owned()),
                if progress.context.is_null() {
                    None
                } else {
                    Some(Box::new(progress) as Box<dyn Progress>)
                },
            )?))
        })
    }
}

